export interface CultureNode {
	id: ProgressionTreeNodeType;
	name: string;
	icon: string;
	turns: number;
	treeType: ProgressionTreeType;
	unlocksByDepth: ChooserDepthInfo[];
	recommendations: AdvisorRecommendations[];
	isLocked?: boolean;
	cost: number;
	progress: number;
	/** The current depth index being researched (0-based). */
	currentDepthIndex: number;
}

/**
 * Build a CultureNode data object for display in the chooser.
 * @param player - The player library.
 * @param nodeType - The progression tree node type.
 * @param isActiveResearch - Whether this node is currently being actively researched.
 * @returns The CultureNode data or null if the node data is not available.
 */
function buildCultureNodeData(
	player: PlayerLibrary,
	nodeType: ProgressionTreeNodeType,
	isActiveResearch = false,
): CultureNode | null {
	const nodeDef = GameInfo.ProgressionTreeNodes.lookup(nodeType);
	const nodeData = Game.ProgressionTrees.getNode(player.id, nodeType);
	if (!nodeDef || !nodeData) return null;

	const unlocksByDepth: ChooserDepthInfo[] = [];

	const treeNodeUnlocks = TreeNodesSupport.getValidNodeUnlocks(nodeData);
	const removableUnlocks = TreeNodesSupport.getRepeatedUniqueUnits(treeNodeUnlocks);

	for (const idx of nodeData.unlockIndices) {
		const unlockInfo = GameInfo.ProgressionTreeNodeUnlocks[idx];
		if (!unlockInfo || unlockInfo.Hidden) continue;

		if (unlockInfo.TargetKind === "KIND_UNIT") {
			const p = Players.get(GameContext.localPlayerID);
			if (p && p.Units?.isBuildPermanentlyDisabled(unlockInfo.TargetType)) continue;
			if (removableUnlocks.includes(unlockInfo.TargetType)) continue;
		}

		const unlockDisplayData = buildUnlockDisplayData(unlockInfo);
		const hasInfo = unlockDisplayData.nameKey.length > 0 || hasUnlockContent(unlockDisplayData.descriptionData);
		if (!hasInfo) continue;

		while (unlocksByDepth.length < unlockInfo.UnlockDepth) {
			const depthIndex = unlocksByDepth.length;
			const isCompleted = depthIndex < nodeData.depthUnlocked;
			const isCurrent = isActiveResearch && depthIndex === nodeData.depthUnlocked;
			unlocksByDepth.push({
				header: "",
				unlocks: [],
				isCompleted,
				isCurrent,
				isLocked: false,
			});
		}
		const depthIdx = unlockInfo.UnlockDepth - 1;
		if (unlockDisplayData.icon) {
			unlocksByDepth[depthIdx].unlocks.push(unlockDisplayData);
		}
	}

	const cultureRecommendations = AdvisorUtilities.getTreeRecommendations(AdvisorySubjectTypes.CHOOSE_CULTURE);
	const recommendations = AdvisorUtilities.getTreeRecommendationIcons(cultureRecommendations, nodeType).map(
		(rec: { class: AdvisorRecommendations }) => rec.class,
	);

	const playerCulture = player?.Culture;
	const cost = playerCulture?.getNodeCost(nodeType) ?? -1;
	const turns = playerCulture?.getTurnsForNode(nodeType) ?? -1;

	return {
		id: nodeType,
		name: getNodeName(nodeData, player),
		icon: GameIcon.getCultureIconFromProgressionTreeNodeDefinition(nodeDef),
		turns,
		treeType: nodeDef.ProgressionTree,
		unlocksByDepth,
		recommendations,
		isLocked: false,
		cost: cost,
		progress: nodeData.progress ?? 0,
		currentDepthIndex: nodeData.depthUnlocked,
	};
}

/**
 * Get the currently active (in-progress) culture node type, if any.
 */
function getActiveCultureNodeType(player: PlayerLibrary): ProgressionTreeNodeType | undefined {
	const cultureTreeType = player?.Culture?.getActiveTree();
	if (cultureTreeType === undefined) return undefined;
	const treeObject = Game.ProgressionTrees.getTree(player.id, cultureTreeType);
	return treeObject?.nodes?.[treeObject.activeNodeIndex]?.nodeType;
}

/**
 * Get all available culture nodes for the player.
 * The active node (if any) will have its isCurrent flags set appropriately.
 */
function getAllCultureNodes(player: PlayerLibrary): CultureNode[] {
	const out: CultureNode[] = [];
	const available = player?.Culture?.getAllAvailableNodeTypes?.();
	if (!available) return out;

	const activeNodeType = getActiveCultureNodeType(player);

	for (const nodeType of available) {
		const isActiveResearch = nodeType === activeNodeType;
		const node = buildCultureNodeData(player, nodeType, isActiveResearch);
		if (node) out.push(node);
	}

	// first show the main tree nodes
	out.sort((node, nodeNext) => {
		const treeType = `${node.treeType}`;
		const treeTypeNext = `${nodeNext.treeType}`;
		const isFirstMainTree = treeType.includes("MAIN");
		const areBothMainTree = treeType.includes("MAIN") && treeTypeNext.includes("MAIN");
		if (areBothMainTree) {
			// for the main tree also order by turns.
			return node.turns - nodeNext.turns;
		} else if (isFirstMainTree) {
			return -1;
		} else {
			return 1;
		}
	});

	return out;
}

function chooseCulture(nodeId: ProgressionTreeNodeType) {
	const nodeIndex = nodeId;
	const args = { ProgressionTreeNodeType: nodeIndex };
	const result = Game.PlayerOperations.canStart(
		GameContext.localPlayerID,
		PlayerOperationTypes.SET_CULTURE_TREE_NODE,
		args,
		false,
	);
	if (result?.Success) {
		Game.PlayerOperations.sendRequest(GameContext.localPlayerID, PlayerOperationTypes.SET_CULTURE_TREE_NODE, args);
	}
}

function openFullTree(defaultNode?: ProgressionTreeNodeType) {
	const player = Players.get(GameContext.localPlayerID);
	const trees = player?.Culture?.getAvailableTrees();
	const treeCSV = trees?.join(",");
	if (!treeCSV) {
		console.error("No culture trees available to open.");
		return;
	}

	let targetNode = defaultNode;
	if (player) {
		const activeTree = player.Culture?.getActiveTree();
		if (activeTree !== undefined) {
			const treeObject = Game.ProgressionTrees.getTree(player.id, activeTree);
			if (treeObject && treeObject.activeNodeIndex < 0) {
				targetNode = undefined;
			}
		}
	}

	const treeParent = document.querySelector<HTMLElement>(".fxs-trees") ?? undefined;
	ContextManager.push("screen-culture-tree", {
		singleton: true,
		createMouseGuard: true,
		targetParent: treeParent,
	});
	if (treeCSV) {
		window.dispatchEvent(
			new CustomEvent("view-culture-progression-tree", {
				detail: {
					treeCSV: treeCSV,
					targetNode: targetNode,
					iconCallback: GameIcon.getCultureIconFromProgressionTreeNodeDefinition,
				},
			}),
		);
	}
	ContextManager.pop("screen-culture-tree-chooser");
}

const CultureTreeChooser = () => {
	// a flag to determine if we should reset the input context on cleanup
	// this primarily exists to prevent resetting the input context to the world when opening the full tree
	let resetInputContext = true;
	const [getClosing, setClosing] = createSignal(false);
	const [allNodes, mutateNodes] = createArraySignal<CultureNode>([]);
	const inProgressNode = createMemo(() => {
		const nodes = allNodes();
		for (const node of nodes) {
			const currentDepth = node.unlocksByDepth[node.currentDepthIndex];
			if (currentDepth?.isCurrent) return node;
		}
		return undefined;
	});

	const defaultNode = createMemo<ProgressionTreeNodeType | undefined>(
		() => inProgressNode()?.id ?? allNodes()[0]?.id,
	);

	function refresh() {
		const player = Players.get(GameContext.localPlayerID);
		if (!player) return;
		const nodes = getAllCultureNodes(player);
		mutateNodes((arr) => {
			arr.length = 0;
			arr.push(...nodes);
		});
	}

	function handleSelect(id: ProgressionTreeNodeType) {
		chooseCulture(id);
		const args = { ProgressionTreeNodeType: ProgressionTreeNodeTypes.NO_NODE };
		Game.PlayerOperations.sendRequest(
			GameContext.localPlayerID,
			PlayerOperationTypes.SET_CULTURE_TREE_TARGET_NODE,
			args,
		);
		setClosing(true);
	}

	function handleOpenFullTree() {
		resetInputContext = false;
		openFullTree(defaultNode());
	}

	onMount(() => {
		refresh();

		type EnginePlayerEvent = { player?: PlayerId } | undefined;
		const listener = (data: EnginePlayerEvent) => {
			if (data?.player !== undefined && data.player !== GameContext.localPlayerID) return;
			refresh();
		};

		UI.sendAudioEvent("culture-tree-chooser-panel-showing");

		const events = [
			"CultureYieldChanged",
			"CultureTreeChanged",
			"CultureTargetChanged",
			"CultureNodeCompleted",
			"PlayerTurnActivated",
			"LocalPlayerTurnBegin",
			"LocalPlayerChanged",
		] as const;
		for (const e of events) engine.on(e, listener);

		onCleanup(() => {
			for (const e of events) engine.off(e, listener);

			if (resetInputContext) {
				Input.setActiveContext(ViewManager.current.getInputContext());
			}
			UI.sendAudioEvent("culture-tree-chooser-panel-hiding");
		});
	});

	return (
		<SidebarChooser
			context="screen-culture-tree-chooser"
			title="LOC_UI_CULTURE_CHOOSER_TITLE"
			id="culture-tree-chooser"
			name="culture-tree-chooser"
			closeButtonAudioGroup="audio-screen-culture-tree-chooser"
			closing={getClosing()}
		>
			<InnerFrame class="my-1\.5">
				<div class="culture-tree-currently-studying self-center w-96">
					<div class="text-accent-4 uppercase mt-1 font-title text-sm tracking-100">
						<L10n.Compose text="LOC_UI_CURRENT_STUDY" />
					</div>
					<div class="filigree-divider-inner-frame w-72 my-1\.5 self-center" />

					<Show
						when={inProgressNode()}
						fallback={
							<div class="flex justify-center items-center w-full min-w-16 font-body text-sm text-accent-4 text-center">
								<L10n.Compose text="LOC_UI_CULTURE_RESEARCH_EMPTY" />
							</div>
						}
					>
						{(node) => (
							<CultureChooserItem
								node={node()}
								onSelect={handleSelect}
							/>
						)}
					</Show>
				</div>
			</InnerFrame>

			<div class="mt-4 mb-2\.5 font-title text-base w-96 self-center uppercase text-center">
				<L10n.Compose text="LOC_UI_CULTURE_CHOOSE_CIVIC_HEADER" />
			</div>
			<ScrollArea class="flex-1">
				<For each={allNodes()}>
					{(node) => (
						<CultureChooserItem
							node={node}
							onSelect={handleSelect}
						/>
					)}
				</For>
			</ScrollArea>

			<Button
				name="OpenFullTree"
				class="mx-8 mt-3 mb-6 uppercase"
				classList={{
					hidden: IsControllerActive(),
				}}
				audio={{
					group: "audio-screen-culture-tree-chooser",
					onFocus: "culture-tree-chooser-focus",
				}}
				disableFocus={IsControllerActive()}
				hotkeyAction="shell-action-1"
				navTrayText="LOC_UI_CULTURE_TREE_VIEW_FULL_TREE_BUTTON"
				onActivate={handleOpenFullTree}
			>
				<L10n.Compose text="LOC_UI_CULTURE_TREE_VIEW_FULL_TREE_BUTTON" />
			</Button>
		</SidebarChooser>
	);
};

window.addEventListener("hotkey-open-civics", () => {
	if (ContextManager.isCurrentClass("screen-culture-tree-chooser")) {
		ContextManager.pop("screen-culture-tree-chooser");
	} else {
		ContextManager.push("screen-culture-tree-chooser", { singleton: true });
	}
});

defineLegacyComponent(
	"screen-culture-tree-chooser",
	{
		classNames: ["screen-culture-tree-chooser", "flex"],
		tabIndex: 0,
	},
	(_attrs, _element) => {
		Input.setActiveContext(InputContext.Shell);
		return <CultureTreeChooser />;
	},
);

ComponentUtilities.loadStyles(style);
